import { isTriggerAvailable, getSortedTriggers } from "./game/common/triggers/trigger";
import { getCurrentState } from "./game/mainSimulationLogic";
  const activablesState = getCurrentState().getInternalStateObject().activables;
  'TRIGGERS'
    + getSortedTriggers()
      .map(item => '<br/><br/>trigger : ' + JSON.stringify(item)
        + '<br/>activable state : ' + JSON.stringify(activablesState[item.uid])
        + '<br/>is available : ' + isTriggerAvailable(getCurrentState(), item));
